import XCTest
@testable import FlashlockCore

/// Replays review sequences generated by the reference implementation
/// (open-spaced-repetition/py-fsrs 6.3.1) and asserts our scheduler produces
/// identical state, stability, difficulty, and due dates.
///
/// Vectors: Resources/fsrs_golden_vectors.json (see the `generator` field for
/// exact provenance). Regenerate with flashlock/scripts/gen_fsrs_vectors.py.
final class FSRSGoldenVectorTests: XCTestCase {

    struct GoldenStep: Decodable {
        let rating: Int
        let reviewedAtOffsetSec: Double
        let state: String
        let stability: Double
        let difficulty: Double
        let dueOffsetSec: Double
    }

    struct GoldenFile: Decodable {
        let generator: String
        let scenarios: [String: [GoldenStep]]
        let retention_08: [String: [GoldenStep]]
    }

    static let start = Date(timeIntervalSince1970: 1_767_225_600) // 2026-01-01T00:00:00Z

    func loadVectors() throws -> GoldenFile {
        let url = try XCTUnwrap(
            Bundle.module.url(
                forResource: "fsrs_golden_vectors", withExtension: "json",
                subdirectory: "Resources"))
        return try JSONDecoder().decode(GoldenFile.self, from: Data(contentsOf: url))
    }

    func replay(_ steps: [GoldenStep], scheduler: FSRS, scenario: String) {
        var card = Card(deckID: UUID(), front: "f", back: "b")
        for (i, step) in steps.enumerated() {
            let reviewedAt = Self.start.addingTimeInterval(step.reviewedAtOffsetSec)
            let rating = Rating(rawValue: step.rating)!
            (card, _) = scheduler.review(card: card, rating: rating, at: reviewedAt)

            let context = "\(scenario) step \(i) (rating \(step.rating))"
            XCTAssertEqual(card.phase.rawValue, step.state, context)
            let memory = card.memory!
            XCTAssertEqual(memory.stability, step.stability,
                           accuracy: max(abs(step.stability) * 1e-9, 1e-12), context)
            XCTAssertEqual(memory.difficulty, step.difficulty, accuracy: 1e-9, context)
            XCTAssertEqual(card.due.timeIntervalSince(Self.start), step.dueOffsetSec,
                           accuracy: 1e-3, context)
        }
    }

    func testGoldenScenariosAtDefaultRetention() throws {
        let vectors = try loadVectors()
        XCTAssertFalse(vectors.scenarios.isEmpty)
        let scheduler = FSRS(enableFuzzing: false)
        for (name, steps) in vectors.scenarios {
            replay(steps, scheduler: scheduler, scenario: name)
        }
    }

    func testGoldenScenarioAtRetention08() throws {
        let vectors = try loadVectors()
        let scheduler = FSRS(desiredRetention: 0.8, enableFuzzing: false)
        for (name, steps) in vectors.retention_08 {
            replay(steps, scheduler: scheduler, scenario: "r=0.8 \(name)")
        }
    }
}
